INSERT INTO `galleries_translations` VALUES ('ar',1,'مثالي','استكشف معرضنا المنسق الذي يضم تصويرًا استثنائيًا وفنًا إبداعيًا.'),('ar',2,'يوم جديد','استكشف معرضنا المنسق الذي يضم تصويرًا استثنائيًا وفنًا إبداعيًا.'),('ar',3,'يوم سعيد','رحلة فنية عبر الألوان والأنسجة واللحظات المجمدة في الزمن.'),('ar',4,'الطبيعة','صور عالية الجودة تعرض الحرفية والاهتمام بالتفاصيل.'),('ar',5,'الصباح','رحلة فنية عبر الألوان والأنسجة واللحظات المجمدة في الزمن.'),('fr',1,'Parfait','Explorez notre galerie organisée mettant en vedette une photographie exceptionnelle et un art créatif.'),('fr',2,'Nouveau Jour','Explorez notre galerie organisée mettant en vedette une photographie exceptionnelle et un art créatif.'),('fr',3,'Jour Heureux','Un voyage artistique à travers les couleurs, les textures et les moments figés dans le temps.'),('fr',4,'Nature','Images de qualité supérieure mettant en valeur l\'artisanat et l\'attention aux détails.'),('fr',5,'Matin','Un voyage artistique à travers les couleurs, les textures et les moments figés dans le temps.'),('id',1,'Sempurna','Jelajahi galeri pilihan kami yang menampilkan fotografi luar biasa dan seni kreatif.'),('id',2,'Hari Baru','Jelajahi galeri pilihan kami yang menampilkan fotografi luar biasa dan seni kreatif.'),('id',3,'Hari Bahagia','Perjalanan artistik melalui warna, tekstur, dan momen yang membeku dalam waktu.'),('id',4,'Alam','Gambar berkualitas premium yang menampilkan keahlian dan perhatian terhadap detail.'),('id',5,'Pagi','Perjalanan artistik melalui warna, tekstur, dan momen yang membeku dalam waktu.'),('tr',1,'Mükemmel','Olağanüstü fotoğrafçılık ve yaratıcı sanat içeren özenle seçilmiş galerimizi keşfedin.'),('tr',2,'Yeni Gün','Olağanüstü fotoğrafçılık ve yaratıcı sanat içeren özenle seçilmiş galerimizi keşfedin.'),('tr',3,'Mutlu Gün','Renkler, dokular ve zamanda donmuş anlar aracılığıyla sanatsal bir yolculuk.'),('tr',4,'Doğa','Ustalığı ve detaylara gösterilen özeni sergileyen premium kalitede görseller.'),('tr',5,'Sabah','Renkler, dokular ve zamanda donmuş anlar aracılığıyla sanatsal bir yolculuk.'),('vi',1,'Hoàn Hảo','Khám phá bộ sưu tập được tuyển chọn của chúng tôi với nhiếp ảnh xuất sắc và nghệ thuật sáng tạo.'),('vi',2,'Ngày Mới','Khám phá bộ sưu tập được tuyển chọn của chúng tôi với nhiếp ảnh xuất sắc và nghệ thuật sáng tạo.'),('vi',3,'Ngày Vui','Hành trình nghệ thuật qua màu sắc, kết cấu và những khoảnh khắc đóng băng trong thời gian.'),('vi',4,'Thiên Nhiên','Hình ảnh chất lượng cao thể hiện tay nghề thủ công và sự chú ý đến từng chi tiết.'),('vi',5,'Buổi Sáng','Hành trình nghệ thuật qua màu sắc, kết cấu và những khoảnh khắc đóng băng trong thời gian.');
