INSERT INTO `testimonials` VALUES (1,'James Dopli','Thanks for all your efforts and teamwork over the last several months!  Thank you so much','main/users/10.jpg','Developer','published','2026-06-29 01:30:51','2026-06-29 01:30:51'),(2,'Theodore Handle','How you use the city or town name is up to you. All results may be freely used in any work.','main/users/8.jpg','CO Founder','published','2026-06-29 01:30:51','2026-06-29 01:30:51'),(3,'Shahnewaz Sakil','Very happy with our choice to take our daughter to Brave care. The entire team was great! Thank you!','main/users/4.jpg','UI/UX Designer','published','2026-06-29 01:30:51','2026-06-29 01:30:51'),(4,'Albert Flores','Wedding day savior! 5 stars. Their bridal collection is a game-changer. Made me feel like a star.','main/users/10.jpg','Bank of America','published','2026-06-29 01:30:51','2026-06-29 01:30:51');
/*!40000 ALTER TABLE `testimonials` ENABLE KEYS */;
